/* ---------- small helpers ---------- */

static int32_t px(const h2_g99_app_t* app, float units) {
  return (int32_t)lroundf(units * app->layout.k);
}

static lv_opa_t opa_of(float value) {
  return (lv_opa_t)lroundf(h2_g99_clamp01(value) * 255.0f);
}

/* LVGL redraws an object on every style set, an unchanged value included,
 * and Main places every element on each loop: set opacity only on change. */
static void set_opa(lv_obj_t* obj, lv_opa_t opa) {
  if (obj != NULL && lv_obj_get_style_opa(obj, LV_PART_MAIN) != opa)
    lv_obj_set_style_opa(obj, opa, LV_PART_MAIN);
}

static void set_image_opa(lv_obj_t* obj, lv_opa_t opa) {
  if (obj != NULL && lv_obj_get_style_image_opa(obj, LV_PART_MAIN) != opa)
    lv_obj_set_style_image_opa(obj, opa, LV_PART_MAIN);
}

static lv_obj_t* plain(lv_obj_t* parent) {
  lv_obj_t* obj = lv_obj_create(parent);
  if (obj == NULL) return NULL;
  lv_obj_remove_style_all(obj);
  lv_obj_set_scrollable(obj, false);
  lv_obj_set_clickable(obj, false);
  return obj;
}

static lv_obj_t* full(lv_obj_t* parent, const h2_g99_app_t* app) {
  lv_obj_t* obj = plain(parent);
  if (obj != NULL) {
    lv_obj_set_pos(obj, 0, 0);
    lv_obj_set_size(obj, app->layout.width, app->layout.height);
  }
  return obj;
}

static lv_obj_t* rect(lv_obj_t* parent, int32_t x, int32_t y, int32_t w,
                      int32_t h, uint32_t rgb, lv_opa_t opa, int32_t radius) {
  lv_obj_t* obj = plain(parent);
  if (obj == NULL) return NULL;
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_size(obj, w, h);
  lv_obj_set_style_bg_color(obj, lv_color_hex(rgb), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(obj, opa, LV_PART_MAIN);
  lv_obj_set_style_radius(obj, radius, LV_PART_MAIN);
  return obj;
}

static lv_obj_t* text(lv_obj_t* parent, const lv_font_t* font, uint32_t rgb,
                      int32_t x, int32_t y, const char* value) {
  lv_obj_t* label = lv_label_create(parent);
  if (label == NULL) return NULL;
  lv_obj_set_style_text_font(label, font, LV_PART_MAIN);
  lv_obj_set_style_text_color(label, lv_color_hex(rgb), LV_PART_MAIN);
  lv_label_set_text(label, value);
  lv_obj_set_pos(label, x, y);
  return label;
}

static lv_obj_t* text_clipped(lv_obj_t* parent, const lv_font_t* font,
                              uint32_t rgb, int32_t x, int32_t y, int32_t w,
                              const char* value) {
  lv_obj_t* label = text(parent, font, rgb, x, y, value);
  if (label != NULL) {
    lv_label_set_long_mode(label, LV_LABEL_LONG_MODE_DOTS);
    lv_obj_set_width(label, w);
  }
  return label;
}

static int32_t line_h(const lv_font_t* font) {
  return lv_font_get_line_height(font);
}

static int32_t text_w(const lv_font_t* font, const char* value) {
  lv_point_t size = {0, 0};
  lv_text_get_size(&size, value, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
  return size.x;
}

static lv_obj_t* image(lv_obj_t* parent, const h2_g99_image_t* img, int32_t x,
                       int32_t y) {
  lv_obj_t* obj = lv_image_create(parent);
  if (obj == NULL) return NULL;
  lv_image_set_src(obj, &img->dsc);
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_clickable(obj, false);
  return obj;
}

static bool image_alloc(h2_g99_app_t* app, h2_g99_image_t* img, int32_t w,
                        int32_t h, lv_color_format_t cf, uint32_t bpp) {
  const size_t size = (size_t)w * (size_t)h * bpp;
  img->pixels = h2_pal_mem_alloc(app->runtime->mem, size);
  if (img->pixels == NULL) return false;
  memset(img->pixels, 0, size);
  memset(&img->dsc, 0, sizeof(img->dsc));
  img->dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
  img->dsc.header.cf = cf;
  img->dsc.header.w = (uint32_t)w;
  img->dsc.header.h = (uint32_t)h;
  img->dsc.header.stride = (uint32_t)w * bpp;
  img->dsc.data_size = (uint32_t)size;
  img->dsc.data = img->pixels;
  return true;
}

static bool argb_alloc(h2_g99_app_t* app, h2_g99_image_t* img, int32_t w,
                       int32_t h) {
  return image_alloc(app, img, w, h, LV_COLOR_FORMAT_ARGB8888, 4u);
}

/* Monochrome wheel art needs only its coverage. Transforming an A8 mask
 * interpolates one channel; the image style supplies the constant colour. */
static void image_to_alpha(h2_g99_app_t* app, h2_g99_image_t* img) {
  const size_t size = (size_t)img->dsc.header.w * img->dsc.header.h;
  for (size_t i = 0u; i < size; ++i) img->pixels[i] = img->pixels[i * 4u + 3u];
  uint8_t* pixels = h2_pal_mem_realloc(app->runtime->mem, img->pixels, size);
  if (pixels != NULL) img->pixels = pixels;
  img->dsc.header.cf = LV_COLOR_FORMAT_A8;
  img->dsc.header.stride = img->dsc.header.w;
  img->dsc.data_size = (uint32_t)size;
  img->dsc.data = img->pixels;
}

static void image_free(h2_g99_app_t* app, h2_g99_image_t* img) {
  if (img->pixels != NULL) h2_pal_mem_free(app->runtime->mem, img->pixels);
  memset(img, 0, sizeof(*img));
}

static bool ready_for_touch(const h2_g99_app_t* app) {
  return !app->press_ignored && app->nav.screen_on &&
         app->library_overlay == NULL && h2_g99_nav_input_ready(&app->nav);
}

static bool wifi_page_selected(const h2_g99_app_t* app) {
  return app->nav.route == H2_G99_ROUTE_SETTINGS &&
         app->nav.sub_sel == H2_G99_SETTING_WIFI;
}

static bool timeout_page_selected(const h2_g99_app_t* app) {
  return app->nav.route == H2_G99_ROUTE_SETTINGS &&
         app->nav.sub_sel == H2_G99_SETTING_SCREEN_TIMEOUT;
}

void h2_g99_ui_wifi_select(h2_g99_app_t* app, uint8_t selection, bool animate) {
  if (app == NULL) return;
  h2_g99_list_select(&app->wifi_motion, selection,
                     app->wifi_state.network_count, app->now_ms, animate);
  app->wifi_motion_ready = true;
}

void h2_g99_ui_timeout_select(h2_g99_app_t* app, uint8_t selection,
                              bool animate) {
  if (app == NULL) return;
  h2_g99_list_select(&app->timeout_motion, selection,
                     H2_G99_SCREEN_TIMEOUT_COUNT, app->now_ms, animate);
  app->timeout_motion_ready = true;
}

static bool list_pressed(const h2_g99_app_t* app) {
  return app->press_wifi || app->press_timeout;
}

static h2_g99_list_motion_t* pressed_motion(h2_g99_app_t* app) {
  return app->press_timeout ? &app->timeout_motion : &app->wifi_motion;
}

static uint8_t pressed_list_count(const h2_g99_app_t* app) {
  return app->press_timeout ? H2_G99_SCREEN_TIMEOUT_COUNT
                            : app->wifi_state.network_count;
}

static void select_pressed_list(h2_g99_app_t* app, uint8_t selection,
                                bool animate) {
  if (app->press_timeout)
    h2_g99_ui_timeout_select(app, selection, animate);
  else
    h2_g99_ui_wifi_select(app, selection, animate);
}

static void request_list_selection(h2_g99_app_t* app) {
  const uint8_t selection = pressed_motion(app)->target;
  if (app->press_timeout) {
    app->touch_request.timeout = selection;
    app->touch_request.feedback |=
        app->settings.screen_timeout_index != selection;
  } else {
    app->touch_request.wifi_focus = selection;
    app->touch_request.feedback |= app->nav.edit_index != selection;
  }
  app->nav.last_input_ms = app->now_ms;
}

static h2_g99_wheel_kind_t wheel_kind(h2_g99_route_t route) {
  return route == H2_G99_ROUTE_LIBRARY ? H2_G99_WHEEL_THUMBS
                                       : H2_G99_WHEEL_ICONS;
}

/* A finger turns the wheel of a page outside editing that has two items or
 * more. */
static bool wheel_turnable(const h2_g99_app_t* app) {
  const h2_g99_nav_t* nav = &app->nav;
  const bool wheel_editor = nav->route == H2_G99_ROUTE_SETTINGS &&
                            (nav->sub_sel == H2_G99_SETTING_WIFI ||
                             nav->sub_sel == H2_G99_SETTING_SCREEN_TIMEOUT ||
                             nav->sub_sel == H2_G99_SETTING_VOLUME ||
                             nav->sub_sel == H2_G99_SETTING_BRIGHTNESS);
  if ((nav->editing && !wheel_editor) || nav->text_entry) return false;
  if (nav->route != H2_G99_ROUTE_MAIN && nav->route != H2_G99_ROUTE_LIBRARY &&
      nav->route != H2_G99_ROUTE_SETTINGS)
    return false;
  return h2_g99_nav_route_count(nav, nav->route) >= 2u;
}

/* Finger travel in pixels per item at the selection, where the wheel moves
 * along its arc at radius times its angular step. */
static float wheel_pitch(const h2_g99_app_t* app) {
  return h2_g99_wheel_step(&app->layout, wheel_kind(app->nav.route)) *
         (float)app->layout.radius;
}

/* ---------- display flush ---------- */

static void display_flush(lv_display_t* display, const lv_area_t* area,
                          uint8_t* pixels) {
  h2_g99_app_t* app = lv_display_get_user_data(display);
  if (app != NULL && !app->suppress_flush && area != NULL && pixels != NULL) {
    const h2_display_rect_t rect_area = {
        area->x1, area->y1, area->x2 - area->x1 + 1, area->y2 - area->y1 + 1};
    const uint64_t draw_start = h2_g99_now_us(app);
    int rc = h2_pal_display_draw_bitmap(
        app->runtime->display, &rect_area, pixels,
        lv_draw_buf_width_to_stride((uint32_t)rect_area.width,
                                    LV_COLOR_FORMAT_RGB565),
        H2_DISPLAY_PIXEL_RGB565);
    const uint64_t draw_end = h2_g99_now_us(app);
    app->frame_draw_us += draw_end - draw_start;
    app->frame_pixels += (uint64_t)rect_area.width * (uint64_t)rect_area.height;
    if (rc == H2_PAL_OK && lv_display_flush_is_last(display)) {
      rc = h2_pal_display_present(app->runtime->display);
      app->frame_present_us += h2_g99_now_us(app) - draw_end;
      app->frame_presented = true;
    }
    if (rc != H2_PAL_OK && app->flush_result == H2_PAL_OK)
      app->flush_result = (h2_pal_result_t)rc;
  }
  lv_display_flush_ready(display);
}

/* ---------- touch ---------- */

static void request_action(h2_g99_app_t* app, h2_g99_action_t action) {
  app->touch_request.action = (int)action;
}

static void on_indev_press(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  /* A finger on the turning wheel stops it on its target at once, so quick
   * consecutive drags all count. */
  if (app->nav.screen_on)
    (void)h2_g99_nav_finish_rotate(&app->nav, app->now_ms);
  /* A press that starts while input is gated is dropped as a whole. */
  app->press_ignored = !app->nav.screen_on || app->library_overlay != NULL ||
                       !h2_g99_nav_input_ready(&app->nav) ||
                       app->nav.route == H2_G99_ROUTE_APP;
  if (!app->nav.screen_on) request_action(app, H2_G99_ACTION_OK);
}

/* Counts one touch read of the current press and its gap to the last. */
static void note_touch_read(h2_g99_app_t* app) {
  const uint64_t now = h2_g99_now_us(app) / 1000u;
  const uint64_t gap = now - app->press_last_ms;
  if (gap > app->press_gap_ms)
    app->press_gap_ms = gap > UINT32_MAX ? UINT32_MAX : (uint32_t)gap;
  app->press_last_ms = now;
  ++app->press_samples;
}

/* Acts on a released press; returns what it did, for the touch log. */
static const char* release_gesture(h2_g99_app_t* app, lv_point_t point) {
  if (!ready_for_touch(app)) {
    if (list_pressed(app))
      select_pressed_list(app, pressed_motion(app)->target, false);
    return "dropped";
  }
  if (list_pressed(app)) {
    h2_g99_list_motion_t* motion = pressed_motion(app);
    const h2_g99_rect_t* viewport =
        app->press_timeout ? &app->timeout_list_rect : &app->wifi_list_rect;
    if (pressed_list_count(app) == 0u) {
      h2_g99_list_release(motion, 0u, app->now_ms);
      return "list empty";
    }
    int selection = motion->target;
    if (point.y >= viewport->y1 && point.y < viewport->y2) {
      const int32_t centre = (viewport->y1 + viewport->y2) / 2;
      selection = (int)lroundf(motion->position + (float)(point.y - centre) /
                                                      (float)app->layout.row_h);
    }
    if (selection < 0) selection = 0;
    select_pressed_list(app, (uint8_t)selection, true);
    request_list_selection(app);
    return app->press_timeout ? "timeout select" : "wifi select";
  }
  const int32_t dy = point.y - app->press_start.y;
  if (dy > px(app, 18.0f) || dy < -px(app, 18.0f)) {
    /* Dragging the wheel up brings the next item to the centre. */
    request_action(app, dy < 0 ? H2_G99_ACTION_DOWN : H2_G99_ACTION_UP);
    return dy < 0 ? "drag down" : "drag up";
  }
  if (app->nav.route == H2_G99_ROUTE_SETTINGS &&
      (app->nav.sub_sel == H2_G99_SETTING_VOLUME ||
       app->nav.sub_sel == H2_G99_SETTING_BRIGHTNESS ||
       app->nav.sub_sel == H2_G99_SETTING_SCREEN_TIMEOUT))
    return "direct control background";
  if (app->nav.editing) return "tap ignored";
  request_action(app, H2_G99_ACTION_OK);
  return "tap ok";
}

/* Turns a turnable wheel with the finger once it moved past the slop. */
static void follow_drag(h2_g99_app_t* app, lv_point_t point) {
  const int32_t dy = point.y - app->press_start.y;
  if (!app->dragging) {
    const int32_t slop = px(app, H2_G99_DRAG_SLOP);
    if ((dy < slop && dy > -slop) || !ready_for_touch(app) ||
        (list_pressed(app) ? pressed_list_count(app) == 0u
                           : !wheel_turnable(app)))
      return;
    app->dragging = true;
  }
  if (list_pressed(app)) {
    h2_g99_list_drag(pressed_motion(app), -(float)dy / (float)app->layout.row_h,
                     pressed_list_count(app), app->now_ms);
    app->nav.last_input_ms = app->now_ms;
    return;
  }
  /* Dragging up brings the next items to the centre. */
  const float pitch = wheel_pitch(app);
  const float target = pitch > 0.0f ? -(float)dy / pitch : 0.0f;
  const uint64_t elapsed =
      app->now_ms >= app->drag_last_ms ? app->now_ms - app->drag_last_ms : 0u;
  app->drag_last_ms = app->now_ms;
  app->drag_offset = h2_g99_wheel_follow(
      app->drag_offset, target, (uint32_t)(elapsed > 50u ? 50u : elapsed));
  app->nav.last_input_ms = app->now_ms;
}

/* A release always starts a finite, damped transition to a magnetic
 * detent, including a small drag that settles back on the current item. */
static void end_drag(h2_g99_app_t* app, char* outcome, size_t size) {
  if (list_pressed(app)) {
    h2_g99_list_motion_t* motion = pressed_motion(app);
    const char* name = app->press_timeout ? "timeout" : "wifi";
    if (!ready_for_touch(app)) {
      select_pressed_list(app, motion->target, false);
      app->dragging = false;
      (void)snprintf(outcome, size, "%s dropped", name);
      return;
    }
    const uint8_t selection =
        h2_g99_list_release(motion, pressed_list_count(app), app->now_ms);
    request_list_selection(app);
    app->dragging = false;
    (void)snprintf(outcome, size, "%s snap index=%u", name,
                   (unsigned)selection);
    return;
  }
  const float offset = app->drag_offset;
  const int steps = h2_g99_wheel_snap(offset);
  app->dragging = false;
  app->drag_offset = 0.0f;
  const h2_g99_nav_result_t result =
      h2_g99_nav_rotate_from(&app->nav, steps, offset, app->now_ms);
  if (result == H2_G99_NAV_CHANGED && steps != 0)
    app->touch_request.feedback = true;
  (void)snprintf(
      outcome, size, "drag offset=%d%% steps=%d%s",
      (int)lroundf(offset * 100.0f), steps,
      result == H2_G99_NAV_CHANGED || offset == 0.0f ? "" : " dropped");
}

static void on_catcher(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  lv_indev_t* indev = lv_indev_active();
  lv_point_t point = {0, 0};
  if (indev != NULL) lv_indev_get_point(indev, &point);
  if (code == LV_EVENT_PRESSED) {
    app->press_active = true;
    app->press_wifi = wifi_page_selected(app) && !app->nav.text_entry &&
                      point.x >= app->layout.panel_x;
    app->press_timeout =
        timeout_page_selected(app) && point.x >= app->layout.panel_x;
    app->press_start = point;
    app->dragging = false;
    app->drag_offset = 0.0f;
    app->drag_last_ms = app->now_ms;
    app->press_samples = 1u;
    app->press_gap_ms = 0u;
    app->press_last_ms = h2_g99_now_us(app) / 1000u;
    app->press_start_ms = app->press_last_ms;
    app->press_touch = app->touch_filter.stats;
    if (ready_for_touch(app)) {
      if (app->wifi_motion.snapping)
        h2_g99_ui_wifi_select(app, app->wifi_motion.target, false);
      if (app->timeout_motion.snapping)
        h2_g99_ui_timeout_select(app, app->timeout_motion.target, false);
      if (list_pressed(app)) {
        h2_g99_list_begin(pressed_motion(app), app->now_ms);
        if (app->press_wifi && app->wifi_state.network_count > 0u)
          app->touch_request.wifi_focus = app->wifi_motion.target;
      }
    }
    return;
  }
  if (code == LV_EVENT_PRESSING) {
    if (!app->press_active) return;
    note_touch_read(app);
    if (ready_for_touch(app)) app->nav.last_input_ms = app->now_ms;
    follow_drag(app, point);
    return;
  }
  if (code == LV_EVENT_PRESS_LOST) {
    char lost[48];
    if (app->press_active && app->dragging) end_drag(app, lost, sizeof(lost));
    if (list_pressed(app)) pressed_motion(app)->dragging = false;
    app->press_active = false;
    return;
  }
  if (code != LV_EVENT_RELEASED || !app->press_active) return;
  app->press_active = false;
  note_touch_read(app);
  char outcome[48];
  if (app->dragging) {
    follow_drag(app, point);
    end_drag(app, outcome, sizeof(outcome));
  } else {
    (void)snprintf(outcome, sizeof(outcome), "%s", release_gesture(app, point));
  }
  /* rejoined: source releases the filter merged back into this press;
   * failed: source reads that failed during it. */
  const h2_g99_touch_stats_t* t = &app->touch_filter.stats;
  h2_g99_log(app,
             "touch start=(%d,%d) end=(%d,%d) dy=%d duration=%llums "
             "reads=%u gap=%ums rejoined=%u failed=%u %s",
             (int)app->press_start.x, (int)app->press_start.y, (int)point.x,
             (int)point.y, (int)(point.y - app->press_start.y),
             (unsigned long long)(app->press_last_ms - app->press_start_ms),
             (unsigned)app->press_samples, (unsigned)app->press_gap_ms,
             (unsigned)(t->rejoined - app->press_touch.rejoined),
             (unsigned)(t->failed - app->press_touch.failed), outcome);
}

static void on_wifi_connect(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  lv_indev_t* indev = lv_indev_active();
  lv_point_t point = {0, 0};
  if (indev != NULL) lv_indev_get_point(indev, &point);
  if (code == LV_EVENT_PRESSED) {
    app->wifi_connect_start = point;
    app->wifi_connect_pressed = ready_for_touch(app);
    app->wifi_connect_dragged = !app->wifi_connect_pressed;
    return;
  }
  if (code == LV_EVENT_PRESSING || code == LV_EVENT_CLICKED) {
    if (ready_for_touch(app)) app->nav.last_input_ms = app->now_ms;
    const int32_t slop = px(app, H2_G99_DRAG_SLOP);
    const int32_t dx = point.x - app->wifi_connect_start.x;
    const int32_t dy = point.y - app->wifi_connect_start.y;
    if (dx >= slop || dx <= -slop || dy >= slop || dy <= -slop)
      app->wifi_connect_dragged = true;
  }
  if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
    app->wifi_connect_pressed = false;
    if (code == LV_EVENT_PRESS_LOST) app->wifi_connect_dragged = true;
  }
  if (code == LV_EVENT_CLICKED && !app->wifi_connect_dragged &&
      ready_for_touch(app) && app->wifi_state.network_count > 0u)
    app->touch_request.row = app->wifi_motion.target;
}

static void on_ok_button(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  if (ready_for_touch(app)) request_action(app, H2_G99_ACTION_OK);
}

static void on_library_menu(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  if (ready_for_touch(app)) app->touch_request.library_menu = 1;
}

static void on_library_close(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  if (!app->nav.screen_on) return;
  if (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING ||
      code == LV_EVENT_CLICKED)
    app->nav.last_input_ms = app->now_ms;
  if (code == LV_EVENT_CLICKED) app->touch_request.library_menu = 0;
}

static void on_library_activity(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  if (app->nav.screen_on) app->nav.last_input_ms = app->now_ms;
}

static void on_slider(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  lv_obj_t* target = lv_event_get_current_target_obj(event);
  const lv_event_code_t code = lv_event_get_code(event);
  if (target == NULL) return;
  if (code == LV_EVENT_PRESSED) app->slider_pressed = ready_for_touch(app);
  if (!app->slider_pressed) return;
  if (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING ||
      code == LV_EVENT_VALUE_CHANGED)
    app->nav.last_input_ms = app->now_ms;
  const bool released =
      code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST;
  if (code == LV_EVENT_VALUE_CHANGED || released)
    app->touch_request.value = (int)lv_slider_get_value(target);
  if (released) {
    app->slider_pressed = false;
    app->touch_request.value_end = true;
  }
}

static void on_keyboard(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  const lv_event_code_t code = lv_event_get_code(event);
  if (code == LV_EVENT_READY) app->touch_request.text = H2_G99_TEXT_SUBMIT;
  if (code == LV_EVENT_CANCEL) app->touch_request.text = H2_G99_TEXT_CANCEL;
}

static void on_haptics(lv_event_t* event) {
  h2_g99_app_t* app = lv_event_get_user_data(event);
  lv_obj_t* target = lv_event_get_current_target_obj(event);
  const lv_event_code_t code = lv_event_get_code(event);
  if (target == NULL) return;
  if (code == LV_EVENT_DELETE) {
    app->haptics_pressed = false;
    return;
  }
  if (code == LV_EVENT_PRESSED) app->haptics_pressed = ready_for_touch(app);
  if (!app->haptics_pressed) return;
  app->nav.last_input_ms = app->now_ms;
  if (code == LV_EVENT_VALUE_CHANGED)
    app->touch_request.haptics = lv_obj_has_state(target, LV_STATE_CHECKED);
  if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST)
    app->haptics_pressed = false;
}

/* ---------- status bar ---------- */

static void add_status(h2_g99_app_t* app, lv_obj_t* parent, int32_t right,
                       int32_t top) {
  const lv_font_t* font = app->font_small;
  char clock[8] = "--:--";
  uint64_t wall_ms = 0u;
  if (h2_pal_time_get_wall_ms(app->runtime->time, &wall_ms) == H2_PAL_OK &&
      wall_ms > 1000000000000ull) {
    const uint64_t minutes =
        wall_ms / 60000u + (uint64_t)H2_G99_UTC_OFFSET_MINUTES;
    (void)snprintf(clock, sizeof(clock), "%02u:%02u",
                   (unsigned)((minutes / 60u) % 24u),
                   (unsigned)(minutes % 60u));
  }
  const int32_t lh = line_h(font);
  int32_t x = right - text_w(font, clock);
  text(parent, font, H2_G99_COLOR_MUTED, x, top, clock);
  const int32_t cy = top + lh / 2;
  if (app->battery_valid) {
    const int32_t bw = px(app, 13.0f);
    const int32_t bh = (int32_t)lroundf((float)font->line_height * 0.45f);
    x -= bw + px(app, 6.0f);
    rect(parent, x, cy - bh / 2, bw, bh, H2_G99_COLOR_MUTED, LV_OPA_40, bh / 3);
    rect(parent, x, cy - bh / 2, bw * app->battery_percent / 100, bh,
         H2_G99_COLOR_MUTED, LV_OPA_COVER, bh / 3);
    rect(parent, x + bw + 1, cy - bh / 5, px(app, 1.4f), (bh * 2) / 5,
         H2_G99_COLOR_MUTED, LV_OPA_40, 1);
  }
  if (app->wifi_state.phase != H2_G99_WIFI_UNAVAILABLE) {
    const int32_t size = (int32_t)app->tiny_wifi.dsc.header.w;
    x -= size + px(app, 4.0f);
    lv_obj_t* icon = image(parent, &app->tiny_wifi, x, cy - size / 2 - 1);
    if (icon != NULL && !app->wifi_state.connected)
      lv_obj_set_style_image_opa(icon, LV_OPA_40, LV_PART_MAIN);
  }
}

/* ---------- info pages ---------- */

static const char* wifi_line(const h2_g99_app_t* app, char* buffer,
                             size_t capacity) {
  const h2_g99_wifi_snapshot_t* w = &app->wifi_state;
  switch (w->phase) {
    case H2_G99_WIFI_UNAVAILABLE:
      return "此设备不支持 Wi-Fi";
    case H2_G99_WIFI_SCANNING:
      return "正在扫描…";
    case H2_G99_WIFI_CONNECTING:
      return "正在连接…";
    default:
      break;
  }
  if (w->connected) {
    (void)snprintf(buffer, capacity, "已连接 %s", w->connected_ssid);
    return buffer;
  }
  if (w->last_was_connect && w->last_result != H2_PAL_OK) {
    (void)snprintf(buffer, capacity, "连接失败（%d）", (int)w->last_result);
    return buffer;
  }
  return "未连接";
}

static int32_t text_height(const h2_g99_app_t* app, const lv_font_t* font,
                           const char* value, int32_t width,
                           int32_t maximum_lines) {
  const int32_t spacing = px(app, 2.0f);
  lv_point_t measured = {0, 0};
  lv_text_get_size(&measured, value, font, 0, spacing, width,
                   LV_TEXT_FLAG_NONE);
  const int32_t maximum =
      line_h(font) * maximum_lines + spacing * (maximum_lines - 1);
  return measured.y < maximum ? measured.y : maximum;
}

static lv_obj_t* panel_text(h2_g99_app_t* app, lv_obj_t* parent,
                            const lv_font_t* font, uint32_t color, int32_t y,
                            const char* value, int32_t maximum_lines) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t width = l->panel_w - 2 * l->panel_inset;
  lv_obj_t* label = text_clipped(parent, font, color, x, y, width, value);
  if (label != NULL) {
    lv_obj_set_height(label,
                      text_height(app, font, value, width, maximum_lines));
    lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_style_text_line_space(label, px(app, 2.0f), LV_PART_MAIN);
  }
  return label;
}

static void centered_info(h2_g99_app_t* app, lv_obj_t* info,
                          const lv_font_t* title_font, const char* title,
                          const char* detail) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t width = l->panel_w - 2 * l->panel_inset;
  const int32_t title_height = line_h(title_font);
  const int32_t body_height =
      text_height(app, app->font_body, detail, width, 2);
  const int32_t gap = px(app, 12.0f);
  const int32_t top = l->cy - (title_height + gap + body_height) / 2;
  panel_text(app, info, title_font, H2_G99_COLOR_TEXT, top, title, 1);
  panel_text(app, info, app->font_body, H2_G99_COLOR_MUTED,
             top + title_height + gap, detail, 2);
}

static void main_info(h2_g99_app_t* app, lv_obj_t* info, uint8_t sel) {
  const h2_g99_layout_t* l = &app->layout;
  add_status(app, info, l->panel_x + l->panel_w - l->panel_inset, l->panel_y);
  char line[96];
  const char* status = "即将推出";
  if (sel == H2_G99_MAIN_LIBRARY) {
    (void)snprintf(line, sizeof(line), "已安装 %u 个应用",
                   (unsigned)H2_G99_LIBRARY_COUNT);
    status = line;
  } else if (sel == H2_G99_MAIN_SETTINGS) {
    char wifi[64];
    const char* w = app->wifi_state.connected
                        ? "Wi-Fi 已连接"
                        : wifi_line(app, wifi, sizeof(wifi));
    if (app->battery_valid)
      (void)snprintf(line, sizeof(line), "%s · 电量 %u%%", w,
                     (unsigned)app->battery_percent);
    else
      (void)snprintf(line, sizeof(line), "%s", w);
    status = line;
  }
  centered_info(app, info, app->font_hero, kMainNames[sel], status);
}

static int32_t content_bottom(const h2_g99_app_t* app) {
  return app->layout.panel_y + app->layout.panel_h - px(app, 12.0f);
}

static int32_t settings_header(h2_g99_app_t* app, lv_obj_t* info,
                               const char* title) {
  const h2_g99_layout_t* l = &app->layout;
  add_status(app, info, l->panel_x + l->panel_w - l->panel_inset, l->panel_y);
  const int32_t top = l->panel_y + line_h(app->font_small) + px(app, 6.0f);
  panel_text(app, info, app->font_title, H2_G99_COLOR_TEXT, top, title, 1);
  return top + line_h(app->font_title) + px(app, 8.0f);
}

static void library_info(h2_g99_app_t* app, lv_obj_t* info) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t cw = l->panel_w - 2 * l->panel_inset;
  const int32_t more_w = px(app, 28.0f);
  const int32_t more_h = px(app, 20.0f);
  const int32_t right = x + cw;
  add_status(app, info, right, l->panel_y);
  const int32_t more_y = l->cy - more_h / 2;
  lv_obj_t* more = rect(info, right - more_w, more_y, more_w, more_h,
                        H2_G99_COLOR_TEXT, LV_OPA_10, px(app, 4.0f));
  if (more != NULL) {
    lv_obj_set_clickable(more, true);
    lv_obj_set_ext_click_area(more, px(app, 4.0f));
    lv_obj_add_event_cb(more, on_library_menu, LV_EVENT_CLICKED, app);
    const int32_t dot = px(app, 2.0f);
    for (int index = -1; index <= 1; ++index)
      rect(more, (more_w - dot) / 2 + index * px(app, 5.0f), (more_h - dot) / 2,
           dot, dot, H2_G99_COLOR_TEXT, LV_OPA_COVER, LV_RADIUS_CIRCLE);
  }
  const int32_t title_h = text_height(app, app->font_title, kAppName, cw, 2);
  const int32_t author_h = line_h(app->font_small);
  const int32_t description_h =
      text_height(app, app->font_body, kAppDescription, cw, 3);
  const int32_t gap = px(app, 8.0f);
  int32_t y = more_y - gap - title_h;
  lv_obj_t* title = text_clipped(info, app->font_title, H2_G99_COLOR_TEXT, x, y,
                                 cw, kAppName);
  if (title != NULL) lv_obj_set_height(title, title_h);
  text_clipped(info, app->font_small, H2_G99_COLOR_MUTED, x,
               more_y + (more_h - author_h) / 2, cw - more_w - px(app, 6.0f),
               kAppAuthor);
  y = more_y + more_h + gap;
  const int32_t button_h = px(app, 22.0f);
  const int32_t button_y = content_bottom(app) - button_h - px(app, 4.0f);
  if (button_y - y > line_h(app->font_body)) {
    lv_obj_t* desc = text_clipped(info, app->font_body, H2_G99_COLOR_MUTED, x,
                                  y, cw, kAppDescription);
    if (desc != NULL) {
      const int32_t available = button_y - y - px(app, 8.0f);
      lv_obj_set_height(desc,
                        description_h < available ? description_h : available);
      lv_obj_set_style_text_line_space(desc, px(app, 2.0f), LV_PART_MAIN);
    }
  }
  lv_obj_t* button = rect(info, x, button_y, cw, button_h, H2_G99_COLOR_PURPLE,
                          LV_OPA_COVER, button_h / 2);
  if (button != NULL) {
    lv_obj_set_clickable(button, true);
    lv_obj_add_event_cb(button, on_ok_button, LV_EVENT_CLICKED, app);
    lv_obj_t* caption =
        text(button, app->font_body, 0xFFFFFFu, 0, 0, "开始游戏");
    if (caption != NULL) lv_obj_center(caption);
  }
}

static void clear_library_menu(h2_g99_app_t* app) {
  lv_obj_t* overlay = app->library_overlay;
  app->library_overlay = NULL;
  app->library_scrim = NULL;
  app->library_drawer = NULL;
  app->library_menu_open = false;
  app->library_menu_progress = 0.0f;
  if (overlay != NULL) lv_obj_delete(overlay);
}

void h2_g99_ui_library_menu(h2_g99_app_t* app, bool open) {
  if (app == NULL || !app->lvgl_ready) return;
  if (app->library_menu_open == open) return;
  if (open && app->library_overlay == NULL) {
    const h2_g99_layout_t* layout = &app->layout;
    const int32_t width = layout->width * 2 / 3;
    const int32_t inset = px(app, 12.0f);
    const int32_t content_w = width - 2 * inset;
    lv_obj_t* overlay = full(app->screen, app);
    if (overlay == NULL) return;
    lv_obj_move_to_index(overlay, (int32_t)lv_obj_get_index(app->blackout));
    lv_obj_t* scrim = rect(overlay, 0, 0, layout->width, layout->height,
                           0x000000u, LV_OPA_COVER, 0);
    lv_obj_t* drawer = rect(overlay, layout->width, 0, width, layout->height,
                            0x1C1234u, LV_OPA_COVER, 0);
    if (scrim == NULL || drawer == NULL) {
      lv_obj_delete(overlay);
      return;
    }
    app->library_overlay = overlay;
    app->library_scrim = scrim;
    app->library_drawer = drawer;
    lv_obj_set_clickable(scrim, true);
    lv_obj_set_press_lock(scrim, true);
    lv_obj_add_event_cb(scrim, on_library_close, LV_EVENT_ALL, app);
    lv_obj_set_clickable(drawer, true);
    lv_obj_add_event_cb(drawer, on_library_activity, LV_EVENT_PRESSING, app);
    const int32_t close_w = px(app, 28.0f);
    const int32_t close_h = px(app, 22.0f);
    lv_obj_t* close =
        rect(drawer, width - inset - close_w, inset, close_w, close_h,
             H2_G99_COLOR_TEXT, LV_OPA_10, px(app, 4.0f));
    if (close != NULL) {
      lv_obj_set_clickable(close, true);
      lv_obj_set_ext_click_area(close, px(app, 4.0f));
      lv_obj_add_event_cb(close, on_library_close, LV_EVENT_ALL, app);
      lv_obj_t* caption =
          text(close, app->font_small, H2_G99_COLOR_TEXT, 0, 0, "关闭");
      if (caption != NULL) lv_obj_center(caption);
    }
    text_clipped(drawer, app->font_title, H2_G99_COLOR_TEXT, inset, inset,
                 content_w - close_w - px(app, 8.0f), "游戏管理");
    int32_t y = inset + line_h(app->font_title) + px(app, 12.0f);
    text_clipped(drawer, app->font_body, H2_G99_COLOR_TEXT, inset, y, content_w,
                 kAppName);
    y += line_h(app->font_body) + px(app, 4.0f);
    text(drawer, app->font_small, H2_G99_COLOR_MUTED, inset, y, "内置游戏");
    y += line_h(app->font_small) + px(app, 12.0f);
    static const struct {
      uint8_t action;
      const char* name;
    } actions[] = {
        {H2_G99_GAME_MOVE_INTERNAL, "移至内部存储"},
        {H2_G99_GAME_MOVE_EXTERNAL, "移至外部存储"},
        {H2_G99_GAME_UNINSTALL, "卸载游戏"},
    };
    const uint8_t available = h2_g99_library_actions(&kOrbitEntry);
    const int32_t row_h = px(app, 30.0f);
    for (size_t index = 0u; index < 3u; ++index) {
      if ((available & actions[index].action) == 0u) continue;
      rect(drawer, inset, y, content_w, 1, H2_G99_COLOR_MUTED, LV_OPA_20, 0);
      lv_obj_t* label =
          text_clipped(drawer, app->font_body, H2_G99_COLOR_MUTED, inset,
                       y + (row_h - line_h(app->font_body)) / 2, content_w,
                       actions[index].name);
      if (label != NULL) lv_obj_set_clickable(label, false);
      y += row_h;
    }
    if (available == 0u) {
      text(drawer, app->font_body, H2_G99_COLOR_TEXT, inset, y, "暂无可用操作");
      y += line_h(app->font_body) + px(app, 8.0f);
    }
    y += px(app, 8.0f);
    lv_obj_t* note =
        text_clipped(drawer, app->font_small, H2_G99_COLOR_MUTED, inset, y,
                     content_w, "内置游戏随系统提供，暂不支持转移或卸载。");
    if (note != NULL) {
      lv_obj_set_style_text_line_space(note, px(app, 2.0f), LV_PART_MAIN);
      lv_obj_set_height(note, layout->height - y - inset);
    }
  }
  app->library_menu_from = app->library_menu_progress;
  app->library_menu_open = open;
  app->library_menu_ms = app->now_ms;
  app->library_menu_duration_ms = open ? 280u : 180u;
  app->nav.last_input_ms = app->now_ms;
}

static void place_library_menu(h2_g99_app_t* app) {
  if (app->library_overlay == NULL) return;
  if (!app->nav.screen_on || app->nav.route != H2_G99_ROUTE_LIBRARY) {
    clear_library_menu(app);
    return;
  }
  const uint64_t elapsed = app->now_ms >= app->library_menu_ms
                               ? app->now_ms - app->library_menu_ms
                               : 0u;
  const float progress =
      h2_g99_clamp01((float)elapsed / (float)app->library_menu_duration_ms);
  const float target = app->library_menu_open ? 1.0f : 0.0f;
  app->library_menu_progress =
      app->library_menu_from +
      (target - app->library_menu_from) * h2_g99_ease_out(progress);
  if (!app->library_menu_open && progress >= 1.0f) {
    clear_library_menu(app);
    return;
  }
  const int32_t width = lv_obj_get_width(app->library_drawer);
  const int32_t left =
      app->layout.width -
      (int32_t)lroundf((float)width * app->library_menu_progress);
  if (lv_obj_get_x(app->library_drawer) != left)
    lv_obj_set_x(app->library_drawer, left);
  set_opa(app->library_scrim, opa_of(app->library_menu_progress * 0.45f));
}

static void wifi_page(h2_g99_app_t* app, h2_g99_layer_t* layer, lv_obj_t* info,
                      int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const h2_g99_wifi_snapshot_t* w = &app->wifi_state;
  const int32_t inset = l->panel_inset;
  char line[64];
  const char* status = wifi_line(app, line, sizeof(line));
  if (w->network_count == 0u) {
    if (w->phase == H2_G99_WIFI_IDLE && !w->connected)
      status = w->last_result == H2_PAL_OK ? "未发现网络" : "扫描暂不可用";
    panel_text(app, info, app->font_body, H2_G99_COLOR_MUTED, y + px(app, 8.0f),
               status, 2);
    app->wifi_list_rect = (h2_g99_rect_t){0};
    return;
  }
  const int32_t width = l->panel_w - 2 * inset;
  panel_text(app, info, app->font_small, H2_G99_COLOR_MUTED, y, status, 2);
  y += text_height(app, app->font_small, status, width, 2) + px(app, 8.0f);
  const int32_t button_h = px(app, 22.0f);
  const int32_t button_y = content_bottom(app) - button_h - px(app, 4.0f);
  const int32_t bottom = button_y - px(app, 6.0f);
  int32_t height = bottom > y ? bottom - y : 1;
  const int32_t above = l->cy - y;
  const int32_t below = bottom - l->cy;
  const int32_t centered_height = 2 * (above < below ? above : below);
  if (centered_height >= l->row_h) {
    height = centered_height;
    y = l->cy - height / 2;
  }
  app->wifi_list_rect =
      (h2_g99_rect_t){l->panel_x, y, l->panel_x + l->panel_w, y + height};
  lv_obj_t* controls = full(info, app);
  if (controls == NULL) return;
  layer->wifi_controls = controls;
  lv_obj_t* viewport = plain(controls);
  if (viewport == NULL) return;
  lv_obj_set_pos(viewport, l->panel_x, y);
  lv_obj_set_size(viewport, l->panel_w, height);
  rect(viewport, 0, (height - l->row_h) / 2, l->panel_w, l->row_h,
       H2_G99_COLOR_PURPLE, LV_OPA_20, px(app, 5.0f));
  for (uint8_t index = 0u; index < w->network_count; ++index) {
    const h2_g99_wifi_network_t* n = &w->networks[index];
    lv_obj_t* row = plain(viewport);
    if (row == NULL) continue;
    layer->wifi_rows[index] = row;
    lv_obj_set_size(row, l->panel_w, l->row_h);
    lv_obj_set_pos(
        row, 0,
        (height - l->row_h) / 2 +
            (int32_t)lroundf(((float)index - app->wifi_motion.position) *
                             (float)l->row_h));
    const bool current =
        w->connected && strcmp(n->ssid, w->connected_ssid) == 0;
    int32_t right = l->panel_w - inset;
    const uint8_t bars = h2_g99_wifi_bars(n->rssi);
    const int32_t bar_w = px(app, 2.2f);
    for (int b = 3; b >= 0; --b) {
      const int32_t bh = px(app, 3.0f + (float)b * 2.4f);
      right -= bar_w;
      rect(row, right, l->row_h / 2 + px(app, 5.0f) - bh, bar_w, bh,
           H2_G99_COLOR_TEXT, b < bars ? LV_OPA_COVER : LV_OPA_20,
           px(app, 0.6f));
      right -= px(app, 1.2f);
    }
    const int32_t tiny = (int32_t)app->tiny_lock.dsc.header.w;
    if (n->security != H2_PAL_WIFI_SECURITY_OPEN) {
      right -= tiny + px(app, 3.0f);
      image(row, &app->tiny_lock, right, (l->row_h - tiny) / 2);
    }
    if (current) {
      right -= tiny + px(app, 3.0f);
      image(row, &app->tiny_check, right, (l->row_h - tiny) / 2);
    }
    const int32_t tx = inset + px(app, 2.0f);
    text_clipped(row, app->font_body, H2_G99_COLOR_TEXT, tx,
                 (l->row_h - line_h(app->font_body)) / 2,
                 right - tx - px(app, 4.0f), n->ssid);
  }
  const int32_t button_x = l->panel_x + inset;
  lv_obj_t* button =
      rect(controls, button_x, button_y, l->panel_w - 2 * inset, button_h,
           H2_G99_COLOR_PURPLE, LV_OPA_COVER, button_h / 2);
  if (button != NULL) {
    layer->wifi_connect = button;
    const bool enabled = w->network_count > 0u && w->phase == H2_G99_WIFI_IDLE;
    lv_obj_set_clickable(button, false);
    lv_obj_set_press_lock(button, true);
    lv_obj_add_event_cb(button, on_wifi_connect, LV_EVENT_ALL, app);
    if (!enabled) set_opa(button, LV_OPA_40);
    lv_obj_t* caption =
        text(button, app->font_body, H2_G99_COLOR_TEXT, 0, 0, "连接");
    if (caption != NULL) lv_obj_center(caption);
  }
}

static void slider_page(h2_g99_app_t* app, h2_g99_layer_t* layer,
                        lv_obj_t* info, uint8_t value) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t cw = l->panel_w - 2 * l->panel_inset;
  char number[8];
  (void)snprintf(number, sizeof(number), "%u%%", (unsigned)value);
  const int32_t number_y = l->cy - line_h(app->font_big) / 2;
  layer->slider_number = panel_text(app, info, app->font_big, H2_G99_COLOR_TEXT,
                                    number_y, number, 1);
  const int32_t th = px(app, 5.0f);
  lv_obj_t* track = lv_slider_create(info);
  if (track != NULL) {
    layer->slider = track;
    lv_obj_remove_style_all(track);
    lv_obj_set_pos(track, x, l->cy + px(app, 36.0f));
    lv_obj_set_size(track, cw, th);
    lv_slider_set_range(track,
                        layer->sel == H2_G99_SETTING_BRIGHTNESS
                            ? H2_G99_BRIGHTNESS_MIN_PERCENT
                            : 0,
                        100);
    lv_slider_set_value(track, value, LV_ANIM_OFF);
    lv_obj_set_style_bg_color(track, lv_color_hex(0xFFFFFFu), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(track, LV_OPA_20, LV_PART_MAIN);
    lv_obj_set_style_radius(track, th / 2, LV_PART_MAIN);
    lv_obj_set_style_bg_color(track, lv_color_hex(H2_G99_COLOR_PURPLE),
                              LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(track, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_radius(track, th / 2, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(track, lv_color_hex(0xFFFFFFu), LV_PART_KNOB);
    lv_obj_set_style_bg_opa(track, LV_OPA_COVER, LV_PART_KNOB);
    lv_obj_set_style_radius(track, LV_RADIUS_CIRCLE, LV_PART_KNOB);
    lv_obj_set_style_pad_all(track, th * 4 / 5, LV_PART_KNOB);
    lv_obj_set_clickable(track, true);
    lv_obj_set_press_lock(track, true);
    lv_obj_set_scroll_chain(track, false);
    lv_obj_set_ext_click_area(track, px(app, 10.0f));
    lv_obj_add_event_cb(track, on_slider, LV_EVENT_ALL, app);
  }
}

static void timeout_page(h2_g99_app_t* app, h2_g99_layer_t* layer,
                         lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const int32_t bottom = content_bottom(app);
  y += px(app, 8.0f);
  const int32_t above = l->cy - y;
  const int32_t below = bottom - l->cy;
  int32_t height = 2 * (above < below ? above : below);
  if (height > 5 * l->row_h) height = 5 * l->row_h;
  if (height < l->row_h) height = l->row_h;
  y = l->cy - height / 2;
  app->timeout_list_rect =
      (h2_g99_rect_t){l->panel_x, y, l->panel_x + l->panel_w, y + height};
  lv_obj_t* viewport = plain(info);
  if (viewport == NULL) return;
  lv_obj_set_pos(viewport, l->panel_x, y);
  lv_obj_set_size(viewport, l->panel_w, height);
  rect(viewport, 0, (height - l->row_h) / 2, l->panel_w, l->row_h,
       H2_G99_COLOR_PURPLE, LV_OPA_20, px(app, 3.0f));
  for (uint8_t index = 0u; index < H2_G99_SCREEN_TIMEOUT_COUNT; ++index) {
    lv_obj_t* row = plain(viewport);
    if (row == NULL) continue;
    layer->timeout_rows[index] = row;
    lv_obj_set_size(row, l->panel_w, l->row_h);
    lv_obj_t* label =
        text_clipped(row, app->font_body, H2_G99_COLOR_TEXT, l->panel_inset,
                     (l->row_h - line_h(app->font_body)) / 2,
                     l->panel_w - 2 * l->panel_inset, kTimeoutNames[index]);
    if (label != NULL)
      lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_y(row, (height - l->row_h) / 2 +
                          (int32_t)lroundf(
                              ((float)index - app->timeout_motion.position) *
                              (float)l->row_h));
  }
}

static void about_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* l = &app->layout;
  const h2_g99_config_t* c = app->config;
  char battery[16] = "—";
  if (app->battery_valid)
    (void)snprintf(battery, sizeof(battery), "%u%%",
                   (unsigned)app->battery_percent);
  const char* const rows[6][2] = {
      {"产品", "GizPocket"},
      {"Main", c->main_version != NULL ? c->main_version : "—"},
      {"Loader", c->loader_version != NULL ? c->loader_version : "—"},
      {"板子", c->board_name != NULL ? c->board_name : "—"},
      {"设备 ID", app->device_id[0] != '\0' ? app->device_id : "—"},
      {"电池", battery},
  };
  const int32_t x = l->panel_x + l->panel_inset;
  const int32_t width = l->panel_w - 2 * l->panel_inset;
  int32_t key_w = 0;
  for (size_t index = 0u; index < 6u; ++index) {
    const int32_t measured = text_w(app->font_small, rows[index][0]);
    if (key_w < measured) key_w = measured;
  }
  const int32_t value_x = x + key_w + px(app, 8.0f);
  const int32_t value_w = width - key_w - px(app, 8.0f);
  const int32_t bottom = content_bottom(app);
  const lv_font_t* value_font = app->font_body;
  int32_t row_heights[6] = {0};
  int32_t gap = px(app, 6.0f);
  int32_t total = 0;
  y += px(app, 8.0f);
  for (unsigned pass = 0u; pass < 3u; ++pass) {
    total = gap * 5;
    for (size_t index = 0u; index < 6u; ++index) {
      int32_t height = text_height(app, value_font, rows[index][1], value_w,
                                   pass == 2u ? 1 : 2);
      if (height < line_h(app->font_small)) height = line_h(app->font_small);
      row_heights[index] = height;
      total += height;
    }
    if (total <= bottom - y) break;
    value_font = app->font_small;
    gap = px(app, 4.0f);
  }
  if (bottom - y > total) y += (bottom - y - total) / 2;
  for (size_t index = 0u; index < 6u; ++index) {
    text(info, app->font_small, H2_G99_COLOR_MUTED, x,
         y + (row_heights[index] - line_h(app->font_small)) / 2,
         rows[index][0]);
    lv_obj_t* value = text_clipped(info, value_font, H2_G99_COLOR_TEXT, value_x,
                                   y, value_w, rows[index][1]);
    if (value != NULL) {
      lv_obj_set_height(value, row_heights[index]);
      lv_obj_set_style_text_line_space(value, px(app, 2.0f), LV_PART_MAIN);
    }
    y += row_heights[index] + gap;
  }
}

static void haptics_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const h2_g99_layout_t* layout = &app->layout;
  const int32_t switch_width = px(app, 46.0f);
  const int32_t switch_height = px(app, 24.0f);
  const int32_t top = y + px(app, 20.0f);
  lv_obj_t* toggle = lv_switch_create(info);
  if (toggle != NULL) {
    lv_obj_remove_style_all(toggle);
    lv_obj_set_pos(toggle,
                   layout->panel_x + (layout->panel_w - switch_width) / 2, top);
    lv_obj_set_size(toggle, switch_width, switch_height);
    lv_obj_set_style_radius(toggle, LV_RADIUS_CIRCLE, LV_PART_MAIN);
    lv_obj_set_style_bg_color(toggle, lv_color_hex(0xFFFFFFu), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(toggle, LV_OPA_20, LV_PART_MAIN);
    lv_obj_set_style_radius(toggle, LV_RADIUS_CIRCLE, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(toggle, lv_color_hex(H2_G99_COLOR_PURPLE),
                              LV_PART_INDICATOR | LV_STATE_CHECKED);
    lv_obj_set_style_bg_opa(toggle, LV_OPA_COVER,
                            LV_PART_INDICATOR | LV_STATE_CHECKED);
    lv_obj_set_style_bg_color(toggle, lv_color_hex(0xFFFFFFu), LV_PART_KNOB);
    lv_obj_set_style_bg_opa(toggle, LV_OPA_COVER, LV_PART_KNOB);
    lv_obj_set_style_radius(toggle, LV_RADIUS_CIRCLE, LV_PART_KNOB);
    lv_obj_set_style_pad_all(toggle, -px(app, 2.0f), LV_PART_KNOB);
    lv_obj_set_style_anim_duration(toggle, 180u, LV_PART_MAIN);
    lv_obj_set_press_lock(toggle, true);
    lv_obj_set_ext_click_area(toggle, px(app, 6.0f));
    if (app->settings.haptics_enabled)
      lv_obj_add_state(toggle, LV_STATE_CHECKED);
    lv_obj_add_event_cb(toggle, on_haptics, LV_EVENT_ALL, app);
  }
  y = top + switch_height + px(app, 12.0f);
  panel_text(app, info, app->font_body, H2_G99_COLOR_TEXT, y,
             app->settings.haptics_enabled ? "已开启" : "已关闭", 1);
  y += line_h(app->font_body) + px(app, 8.0f);
  panel_text(
      app, info, app->font_small, H2_G99_COLOR_MUTED, y,
      app->haptics_available ? "操作时提供轻触反馈" : "当前环境仅保存设置", 2);
}

static void format_bytes(uint64_t bytes, char* out, size_t capacity) {
  const uint64_t mib = 1024u * 1024u;
  if (bytes >= mib)
    (void)snprintf(out, capacity, "%.1f MB", (double)bytes / (double)mib);
  else
    (void)snprintf(out, capacity, "%.0f KB", (double)bytes / 1024.0);
}

static void storage_volume(h2_g99_app_t* app, lv_obj_t* info, int32_t y,
                           const char* name,
                           const h2_g99_storage_volume_t* volume) {
  const h2_g99_layout_t* layout = &app->layout;
  const int32_t width = layout->panel_w - 2 * layout->panel_inset;
  const int32_t height =
      line_h(app->font_small) + line_h(app->font_body) + px(app, 20.0f);
  const int32_t x = layout->panel_x + layout->panel_inset;
  const int32_t radius = px(app, 2.0f);
  lv_obj_t* frame =
      rect(info, x, y, width, height, 0x24183Au, LV_OPA_90, radius);
  if (frame == NULL) return;
  lv_obj_set_style_border_color(frame, lv_color_hex(H2_G99_COLOR_MUTED),
                                LV_PART_MAIN);
  lv_obj_set_style_border_opa(frame, LV_OPA_30, LV_PART_MAIN);
  lv_obj_set_style_border_width(frame, 1, LV_PART_MAIN);
  if (volume->result == H2_PAL_OK && volume->total_bytes > 0u) {
    const int32_t filled =
        (int32_t)((double)(width - 2) * (double)volume->used_bytes /
                  (double)volume->total_bytes);
    if (filled > 0)
      rect(frame, 1, 1, filled, height - 2, 0x56338Du, LV_OPA_COVER, radius);
  }
  char value[64];
  if (volume->result == H2_PAL_OK) {
    char used[24], total[24];
    format_bytes(volume->used_bytes, used, sizeof(used));
    format_bytes(volume->total_bytes, total, sizeof(total));
    (void)snprintf(value, sizeof(value), "%s / %s", used, total);
  } else {
    (void)snprintf(value, sizeof(value), "%s",
                   app->storage_state.pending                 ? "正在读取…"
                   : volume->result == H2_PAL_ERR_UNSUPPORTED ? "暂不可用"
                                                              : "读取失败");
  }
  const int32_t inset = px(app, 8.0f);
  lv_obj_t* name_label =
      text_clipped(frame, app->font_small, H2_G99_COLOR_TEXT, inset,
                   px(app, 6.0f), width - 2 * inset, name);
  lv_obj_t* value_label = text_clipped(
      frame, app->font_body, H2_G99_COLOR_TEXT, inset,
      px(app, 10.0f) + line_h(app->font_small), width - 2 * inset, value);
  if (name_label != NULL) {
    lv_obj_set_height(name_label, line_h(app->font_small));
    lv_obj_set_style_text_align(name_label, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
  }
  if (value_label != NULL) {
    lv_obj_set_height(value_label, line_h(app->font_body));
    lv_obj_set_style_text_align(value_label, LV_TEXT_ALIGN_CENTER,
                                LV_PART_MAIN);
  }
}

static void storage_page(h2_g99_app_t* app, lv_obj_t* info, int32_t y) {
  const int32_t block_height =
      line_h(app->font_small) + line_h(app->font_body) + px(app, 20.0f);
  const int32_t gap = px(app, 18.0f);
  const int32_t caption_height = line_h(app->font_small) + px(app, 12.0f);
  const int32_t available = content_bottom(app) - y;
  const int32_t total = block_height * 2 + gap + caption_height;
  if (available > total) y += (available - total) / 2;
  storage_volume(app, info, y, "内部存储", &app->storage_state.internal);
  y += block_height + gap;
  storage_volume(app, info, y, "外部存储", &app->storage_state.external);
  y += block_height + px(app, 12.0f);
  panel_text(
      app, info, app->font_small, H2_G99_COLOR_MUTED, y,
      app->storage_state.simulated ? "预览数据 · 已用 / 总量" : "已用 / 总量",
      1);
}

static void settings_info(h2_g99_app_t* app, h2_g99_layer_t* layer,
                          lv_obj_t* info, uint8_t sel) {
  if (!h2_g99_nav_setting_implemented(sel)) {
    const h2_g99_layout_t* l = &app->layout;
    add_status(app, info, l->panel_x + l->panel_w - l->panel_inset, l->panel_y);
    centered_info(app, info, app->font_title, kSettingNames[sel], "暂未开放");
    return;
  }
  const int32_t y = settings_header(app, info, kSettingNames[sel]);
  switch (sel) {
    case H2_G99_SETTING_WIFI:
      wifi_page(app, layer, info, y);
      break;
    case H2_G99_SETTING_VOLUME:
      slider_page(app, layer, info, app->settings.volume_percent);
      break;
    case H2_G99_SETTING_BRIGHTNESS:
      slider_page(app, layer, info, app->settings.brightness_percent);
      break;
    case H2_G99_SETTING_SCREEN_TIMEOUT:
      timeout_page(app, layer, info, y);
      break;
    case H2_G99_SETTING_ABOUT:
      about_page(app, info, y);
      break;
    case H2_G99_SETTING_HAPTICS:
      haptics_page(app, info, y);
      break;
    case H2_G99_SETTING_STORAGE:
      storage_page(app, info, y);
      break;
    default:
      break;
  }
}

static void build_info(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  if (layer->wifi_controls == NULL) layer->wifi_reveal_ms = app->now_ms;
  lv_obj_clean(layer->info);
  memset(layer->wifi_rows, 0, sizeof(layer->wifi_rows));
  memset(layer->timeout_rows, 0, sizeof(layer->timeout_rows));
  layer->wifi_controls = NULL;
  layer->wifi_connect = NULL;
  layer->slider = NULL;
  layer->slider_number = NULL;
  /* Keep page coordinates in screen units, while the parent clips opacity
   * changes and invalidation to the actual info area. */
  lv_obj_t* content = full(layer->info, app);
  if (content == NULL) return;
  lv_obj_set_pos(content, -app->layout.panel_x, -app->layout.panel_y);
  switch (layer->route) {
    case H2_G99_ROUTE_MAIN:
    case H2_G99_ROUTE_BOOT:
      main_info(app, content, layer->sel);
      break;
    case H2_G99_ROUTE_LIBRARY:
      library_info(app, content);
      break;
    case H2_G99_ROUTE_SETTINGS:
      settings_info(app, layer, content, layer->sel);
      break;
    default:
      break;
  }
}

static void show_page(h2_g99_app_t* app, h2_g99_layer_t* layer,
                      h2_g99_route_t route, uint8_t sel) {
  if (route == H2_G99_ROUTE_BOOT) route = H2_G99_ROUTE_MAIN;
  const bool same_page =
      layer->built && layer->route == route && layer->sel == sel;
  const bool wifi_moving =
      route == H2_G99_ROUTE_SETTINGS && sel == H2_G99_SETTING_WIFI &&
      ((app->press_active && app->press_wifi) || app->wifi_connect_pressed ||
       app->wifi_motion.dragging || app->wifi_motion.snapping);
  const bool timeout_moving =
      route == H2_G99_ROUTE_SETTINGS && sel == H2_G99_SETTING_SCREEN_TIMEOUT &&
      ((app->press_active && app->press_timeout) ||
       app->timeout_motion.dragging || app->timeout_motion.snapping);
  if (!same_page ||
      (layer->info_rev != app->info_rev && !wifi_moving && !timeout_moving &&
       !app->slider_pressed && !app->haptics_pressed)) {
    layer->route = route;
    layer->sel = sel;
    layer->info_rev = app->info_rev;
    layer->built = true;
    build_info(app, layer);
  }
  lv_obj_set_hidden(layer->wheel, false);
  lv_obj_set_hidden(layer->info, false);
}

static void place_wifi(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  if (layer->route != H2_G99_ROUTE_SETTINGS ||
      layer->sel != H2_G99_SETTING_WIFI)
    return;
  const int32_t height = app->wifi_list_rect.y2 - app->wifi_list_rect.y1;
  for (uint8_t index = 0u; index < H2_G99_WIFI_MAX_NETWORKS; ++index) {
    lv_obj_t* row = layer->wifi_rows[index];
    if (row == NULL) continue;
    const float distance = (float)index - app->wifi_motion.position;
    const int32_t top = (height - app->layout.row_h) / 2 +
                        (int32_t)lroundf(distance * (float)app->layout.row_h);
    const bool visible = top < height && top + app->layout.row_h > 0;
    lv_obj_set_hidden(row, !visible);
    if (!visible) continue;
    lv_obj_set_y(row, top);
    float opacity = 1.0f - fabsf(distance) * 0.25f;
    if (opacity < 0.25f) opacity = 0.25f;
    set_opa(row, opa_of(opacity));
  }
}

static void place_slider(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  if (layer->slider == NULL || layer->slider_number == NULL) return;
  const uint8_t value = layer->sel == H2_G99_SETTING_VOLUME
                            ? app->settings.volume_percent
                            : app->settings.brightness_percent;
  if (!app->slider_pressed && lv_slider_get_value(layer->slider) != value)
    lv_slider_set_value(layer->slider, value, LV_ANIM_OFF);
  char number[8];
  (void)snprintf(number, sizeof(number), "%u%%", (unsigned)value);
  if (strcmp(lv_label_get_text(layer->slider_number), number) != 0)
    lv_label_set_text(layer->slider_number, number);
}

static void place_timeout(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  if (layer->route != H2_G99_ROUTE_SETTINGS ||
      layer->sel != H2_G99_SETTING_SCREEN_TIMEOUT)
    return;
  const int32_t height = app->timeout_list_rect.y2 - app->timeout_list_rect.y1;
  for (uint8_t index = 0u; index < H2_G99_SCREEN_TIMEOUT_COUNT; ++index) {
    lv_obj_t* row = layer->timeout_rows[index];
    if (row == NULL) continue;
    const float distance = (float)index - app->timeout_motion.position;
    const int32_t top = (height - app->layout.row_h) / 2 +
                        (int32_t)lroundf(distance * (float)app->layout.row_h);
    const bool visible = top < height && top + app->layout.row_h > 0;
    lv_obj_set_hidden(row, !visible);
    if (!visible) continue;
    lv_obj_set_y(row, top);
    float opacity = 1.0f - fabsf(distance) * 0.3f;
    if (opacity < 0.2f) opacity = 0.2f;
    set_opa(row, opa_of(opacity));
  }
}

static void hide_layer(h2_g99_layer_t* layer) {
  lv_obj_set_hidden(layer->wheel, true);
  lv_obj_set_hidden(layer->info, true);
}

/* ---------- wheel ---------- */

typedef struct placed {
  float d;
  int item;
  h2_g99_slot_t slot;
} placed_t;

static int32_t wheel_width(const h2_g99_app_t* app) {
  const int32_t right =
      app->layout.sel_x + (app->glow_px + 1) / 2 + px(app, 2.0f);
  return right < app->layout.width ? right : app->layout.width;
}

static const h2_g99_image_t* item_image(h2_g99_app_t* app, h2_g99_route_t route,
                                        int item) {
  if (route == H2_G99_ROUTE_LIBRARY) return &app->cover;
  if (route == H2_G99_ROUTE_SETTINGS) return &app->icons[kSettingIcons[item]];
  return &app->icons[kMainIcons[item]];
}

static void apply_slots(h2_g99_app_t* app, h2_g99_layer_t* layer,
                        h2_g99_route_t route, placed_t* list, int count,
                        int32_t dx) {
  lv_obj_set_hidden(layer->poster, true);
  const int32_t viewport_width = wheel_width(app);
  if (lv_obj_get_width(layer->wheel) != viewport_width)
    lv_obj_set_width(layer->wheel, viewport_width);
  /* Draw far slots first so the selection stays on top. */
  for (int i = 1; i < count; ++i) {
    placed_t key = list[i];
    int j = i - 1;
    while (j >= 0 && fabsf(list[j].d) < fabsf(key.d)) {
      list[j + 1] = list[j];
      --j;
    }
    list[j + 1] = key;
  }
  const bool thumbs = route == H2_G99_ROUTE_LIBRARY;
  const int32_t base = thumbs ? app->thumb_px : app->icon_px;
  float best_glow = 0.0f;
  const h2_g99_slot_t* glow_slot = NULL;
  for (int i = 0; i < H2_G99_WHEEL_SLOTS; ++i) {
    lv_obj_t* obj = layer->slots[i];
    if (i >= count || list[i].slot.size < 1.0f ||
        list[i].slot.opacity <= 0.0f) {
      lv_obj_set_hidden(obj, true);
      continue;
    }
    const placed_t* p = &list[i];
    const h2_g99_image_t* img = item_image(app, route, p->item);
    if (layer->slot_src[i] != img) {
      lv_image_set_src(obj, &img->dsc);
      layer->slot_src[i] = img;
    }
    lv_obj_set_hidden(obj, false);
    lv_obj_set_pos(obj, (int32_t)lroundf(p->slot.x) - base / 2 + dx,
                   (int32_t)lroundf(p->slot.y) - base / 2);
    lv_image_set_scale(obj,
                       (uint32_t)lroundf(p->slot.size / (float)base * 256.0f));
    lv_image_set_rotation(obj, (int32_t)lroundf(p->slot.tilt_deg * 10.0f));
    set_image_opa(obj, opa_of(p->slot.opacity));
    if (p->slot.glow > best_glow) {
      best_glow = p->slot.glow;
      glow_slot = &p->slot;
    }
  }
  if (glow_slot == NULL) {
    lv_obj_set_hidden(layer->glow, true);
    return;
  }
  const float diameter = thumbs
                             ? glow_slot->size * 1.35f + 6.0f * app->layout.k
                             : glow_slot->size * 1.24f + 12.0f * app->layout.k;
  lv_obj_set_hidden(layer->glow, false);
  lv_obj_set_pos(layer->glow,
                 (int32_t)lroundf(glow_slot->x) - app->glow_px / 2 + dx,
                 (int32_t)lroundf(glow_slot->y) - app->glow_px / 2);
  lv_image_set_scale(
      layer->glow, (uint32_t)lroundf(diameter / (float)app->glow_px * 256.0f));
  set_image_opa(layer->glow, opa_of((thumbs ? 0.55f : 0.5f) * best_glow));
}

static void place_wheel(h2_g99_app_t* app, h2_g99_layer_t* layer,
                        h2_g99_route_t route, float sel, float dx) {
  if (route == H2_G99_ROUTE_BOOT) route = H2_G99_ROUTE_MAIN;
  if (route == H2_G99_ROUTE_LIBRARY) {
    lv_obj_set_hidden(layer->glow, true);
    for (size_t index = 0u; index < H2_G99_WHEEL_SLOTS; ++index)
      lv_obj_set_hidden(layer->slots[index], true);
    if (lv_obj_get_width(layer->wheel) != app->layout.width)
      lv_obj_set_width(layer->wheel, app->layout.width);
    lv_obj_set_hidden(layer->poster, false);
    const int32_t left = (int32_t)lroundf(dx);
    if (lv_obj_get_x(layer->poster) != left) lv_obj_set_x(layer->poster, left);
    return;
  }
  const int n = (int)h2_g99_nav_route_count(&app->nav, route);
  placed_t list[H2_G99_WHEEL_SLOTS];
  int count = 0;
  const h2_g99_wheel_kind_t kind =
      route == H2_G99_ROUTE_LIBRARY ? H2_G99_WHEEL_THUMBS : H2_G99_WHEEL_ICONS;
  const int base = (int)lroundf(sel);
  int32_t lo = -3;
  int32_t hi = 3;
  if (n < 5) h2_g99_wheel_span((uint32_t)n, &lo, &hi);
  for (int off = lo; off <= hi && count < H2_G99_WHEEL_SLOTS && n > 0; ++off) {
    const int j = base + off;
    const float d = (float)j - sel;
    if (fabsf(d) >= 2.9f) continue;
    list[count].d = d;
    list[count].item =
        h2_g99_nav_wheel_item(route, (uint8_t)(((j % n) + n) % n));
    h2_g99_wheel_slot(&app->layout, kind, d, &list[count].slot);
    ++count;
  }
  apply_slots(app, layer, route, list, count, (int32_t)lroundf(dx));
}

static void place_boot_wheel(h2_g99_app_t* app, h2_g99_layer_t* layer,
                             float unfold) {
  placed_t list[5];
  for (int d = -2; d <= 2; ++d) {
    list[d + 2].d = (float)d;
    list[d + 2].item = H2_G99_MAIN_LIBRARY + d;
    h2_g99_boot_slot(&app->layout, d, unfold, &list[d + 2].slot);
  }
  apply_slots(app, layer, H2_G99_ROUTE_MAIN, list, 5, 0);
}

static void set_layer(const h2_g99_app_t* app, h2_g99_layer_t* layer,
                      float wheel_opacity, float info_opacity) {
  /* Animate the actual elements. Moving/fading an empty container invalidates
   * its whole column or panel even though only sparse children changed. */
  const lv_opa_t wheel = opa_of(wheel_opacity);
  set_opa(layer->poster, wheel);
  set_opa(layer->glow, wheel);
  for (size_t i = 0u; i < H2_G99_WHEEL_SLOTS; ++i)
    set_opa(layer->slots[i], wheel);
  lv_obj_t* content = lv_obj_get_child(layer->info, 0);
  if (content != NULL) {
    const lv_opa_t info = opa_of(info_opacity);
    for (uint32_t i = 0u; i < lv_obj_get_child_count(content); ++i) {
      lv_obj_t* child = lv_obj_get_child(content, (int32_t)i);
      if (child == layer->wifi_controls) {
        const uint64_t elapsed = app->now_ms >= layer->wifi_reveal_ms
                                     ? app->now_ms - layer->wifi_reveal_ms
                                     : 0u;
        const float progress =
            h2_g99_clamp01((float)elapsed / (float)H2_G99_WIFI_REVEAL_MS);
        const float remaining = 1.0f - progress;
        const float reveal = 1.0f - remaining * remaining * remaining;
        set_opa(child, opa_of(info_opacity * reveal));
        if (layer->wifi_connect != NULL)
          lv_obj_set_clickable(layer->wifi_connect,
                               elapsed >= H2_G99_WIFI_REVEAL_MS &&
                                   app->wifi_state.phase == H2_G99_WIFI_IDLE);
      } else {
        set_opa(child, info);
      }
    }
  }
}

/* ---------- frame ---------- */

static void finish_boot(h2_g99_app_t* app) {
  if (app->brand_icon != NULL) {
    lv_obj_delete(app->brand_icon);
    app->brand_icon = NULL;
  }
  if (app->wordmark != NULL) {
    lv_obj_delete(app->wordmark);
    app->wordmark = NULL;
  }
  image_free(app, &app->brand);
  image_free(app, &app->mark);
  set_opa(app->background, LV_OPA_COVER);
}

void h2_g99_ui_frame(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready || app->nav.route == H2_G99_ROUTE_APP)
    return;
  place_library_menu(app);
  if (wifi_page_selected(app)) {
    if (!app->wifi_motion_ready)
      h2_g99_ui_wifi_select(app, app->nav.editing ? app->nav.edit_index : 0u,
                            false);
    h2_g99_list_tick(&app->wifi_motion, app->now_ms);
  } else {
    app->wifi_motion_ready = false;
    h2_g99_list_select(&app->wifi_motion, 0u, app->wifi_state.network_count,
                       app->now_ms, false);
  }
  if (timeout_page_selected(app)) {
    if (!app->timeout_motion_ready)
      h2_g99_ui_timeout_select(app, app->settings.screen_timeout_index, false);
    h2_g99_list_tick(&app->timeout_motion, app->now_ms);
  } else {
    app->timeout_motion_ready = false;
    h2_g99_list_select(&app->timeout_motion, app->settings.screen_timeout_index,
                       H2_G99_SCREEN_TIMEOUT_COUNT, app->now_ms, false);
  }
  h2_g99_nav_t* nav = &app->nav;
  h2_g99_layer_t* f = &app->layers[app->front];
  h2_g99_layer_t* b = &app->layers[1 - app->front];
  const float p = h2_g99_nav_progress(nav, app->now_ms);
  switch (nav->anim) {
    case H2_G99_TRANSITION_BOOT: {
      h2_g99_boot_frame_t frame;
      h2_g99_boot_frame(h2_g99_nav_elapsed(nav, app->now_ms), &frame);
      set_opa(app->background, opa_of(frame.background_opacity));
      set_opa(app->brand_icon, opa_of(frame.brand_opacity));
      set_opa(app->wordmark, opa_of(frame.brand_opacity));
      show_page(app, f, H2_G99_ROUTE_MAIN, H2_G99_MAIN_LIBRARY);
      place_boot_wheel(app, f, frame.unfold);
      set_layer(app, f, 1.0f, frame.info_opacity);
      hide_layer(b);
      return;
    }
    case H2_G99_TRANSITION_ENTER:
    case H2_G99_TRANSITION_BACK: {
      h2_g99_page_frame_t frame;
      h2_g99_page_frame(&app->layout, p, &frame);
      show_page(app, f, nav->from_route, nav->from_sel);
      show_page(app, b, nav->to_route, nav->to_sel);
      place_wheel(
          app, f, nav->from_route,
          (float)h2_g99_nav_wheel_position(nav->from_route, nav->from_sel),
          frame.old_wheel_dx);
      place_wheel(app, b, nav->to_route,
                  (float)h2_g99_nav_wheel_position(nav->to_route, nav->to_sel),
                  frame.new_wheel_dx);
      set_layer(app, f, frame.old_wheel_opacity, frame.old_info_opacity);
      set_layer(app, b, frame.new_wheel_opacity, frame.new_info_opacity);
      app->swap_pending = true;
      return;
    }
    case H2_G99_TRANSITION_ROTATE: {
      /* Ease from the released position to its detent. Project the target
       * information once; an opacity fade would repaint it every frame. */
      const float sel =
          (float)h2_g99_nav_wheel_position(nav->route, nav->from_sel) +
          nav->rotate_from +
          ((float)nav->rotate_dir - nav->rotate_from) * h2_g99_ease_snap(p);
      show_page(app, f, nav->route, nav->to_sel);
      place_wheel(app, f, nav->route, sel, 0.0f);
      set_layer(app, f, 1.0f, 1.0f);
      hide_layer(b);
      return;
    }
    default:
      break;
  }
  if (app->brand_icon != NULL || app->wordmark != NULL) finish_boot(app);
  if (app->swap_pending) {
    app->swap_pending = false;
    app->front = (uint8_t)(1 - app->front);
    f = &app->layers[app->front];
    b = &app->layers[1 - app->front];
  }
  const uint8_t sel =
      nav->route == H2_G99_ROUTE_MAIN ? nav->main_sel : nav->sub_sel;
  /* A finger moves only the wheel until a detent is committed. */
  const bool dragged =
      app->dragging && !list_pressed(app) && wheel_turnable(app);
  const float position = (float)h2_g99_nav_wheel_position(nav->route, sel) +
                         (dragged ? app->drag_offset : 0.0f);
  /* Keep the committed selection while held. Rebuild its information
   * once at snap, rather than repeatedly at a noisy half-slot crossing. */
  show_page(app, f, nav->route, sel);
  place_wheel(app, f, nav->route, position, 0.0f);
  place_wifi(app, f);
  place_timeout(app, f);
  place_slider(app, f);
  set_layer(app, f, 1.0f, 1.0f);
  hide_layer(b);
  lv_obj_update_layout(app->screen);
}

void h2_g99_ui_pump(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  const uint64_t delta = app->now_ms - app->last_tick_ms;
  app->last_tick_ms = app->now_ms;
  lv_tick_inc((uint32_t)(delta > 1000u ? 1000u : delta));
  (void)lv_timer_handler();
}

/* ---------- screen, suspend, keyboard ---------- */

void h2_g99_ui_set_screen(h2_g99_app_t* app, bool on) {
  if (app == NULL || !app->lvgl_ready) return;
  const h2_pal_display_t* display = app->runtime->display;
  if (on) {
    (void)h2_pal_display_set_brightness_percent(
        display, app->settings.brightness_percent);
    if (app->nav.route == H2_G99_ROUTE_APP) return;
    lv_obj_set_hidden(app->blackout, true);
    app->suppress_flush = false;
    lv_obj_invalidate(app->screen);
    return;
  }
  clear_library_menu(app);
  if (app->nav.route != H2_G99_ROUTE_APP) {
    lv_obj_set_hidden(app->blackout, false);
    lv_refr_now(app->display);
    app->suppress_flush = true;
  }
  (void)h2_pal_display_set_brightness_percent(display, 0u);
}

void h2_g99_ui_suspend(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  lv_refr_now(app->display);
  app->suppress_flush = true;
  lv_timer_pause(lv_display_get_refr_timer(app->display));
}

void h2_g99_ui_resume(h2_g99_app_t* app) {
  if (app == NULL || !app->lvgl_ready) return;
  app->suppress_flush = !app->nav.screen_on;
  lv_timer_resume(lv_display_get_refr_timer(app->display));
  app->info_rev++;
  lv_obj_invalidate(app->screen);
}

void h2_g99_ui_open_keyboard(h2_g99_app_t* app, const char* ssid) {
  if (app == NULL || !app->lvgl_ready || app->keyboard_panel != NULL) return;
  const h2_g99_layout_t* l = &app->layout;
  (void)snprintf(app->keyboard_ssid, sizeof(app->keyboard_ssid), "%s",
                 ssid != NULL ? ssid : "");
  lv_obj_t* panel = full(app->screen, app);
  if (panel == NULL) return;
  lv_obj_move_to_index(panel, (int32_t)lv_obj_get_index(app->blackout));
  lv_obj_set_style_bg_color(panel, lv_color_hex(0x0B0620u), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(panel, LV_OPA_90, LV_PART_MAIN);
  lv_obj_set_clickable(panel, true);
  char title[64];
  (void)snprintf(title, sizeof(title), "连接 %s", app->keyboard_ssid);
  const int32_t x = l->pad * 2;
  text_clipped(panel, app->font_body, H2_G99_COLOR_TEXT, x, l->pad,
               l->width - 4 * l->pad, title);
  lv_obj_t* area = lv_textarea_create(panel);
  lv_obj_t* keyboard = lv_keyboard_create(panel);
  if (area == NULL || keyboard == NULL) {
    lv_obj_delete(panel);
    return;
  }
  const int32_t field_y = l->pad + line_h(app->font_body) + px(app, 6.0f);
  lv_obj_set_pos(area, x, field_y);
  lv_obj_set_size(area, l->width - 4 * l->pad,
                  line_h(app->font_body) + px(app, 12.0f));
  lv_textarea_set_one_line(area, true);
  lv_textarea_set_password_mode(area, true);
  lv_textarea_set_max_length(area, H2_PAL_WIFI_PASSWORD_MAX);
  lv_textarea_set_placeholder_text(area, "密码");
  lv_obj_set_style_text_font(area, app->font_body, LV_PART_MAIN);
  lv_obj_set_style_text_font(area, app->font_body,
                             LV_PART_TEXTAREA_PLACEHOLDER);
  const int32_t keyboard_y = field_y + line_h(app->font_body) + px(app, 20.0f);
  lv_obj_set_pos(keyboard, 0, keyboard_y);
  lv_obj_set_size(keyboard, l->width, l->height - keyboard_y);
  lv_keyboard_set_textarea(keyboard, area);
  lv_obj_add_event_cb(keyboard, on_keyboard, LV_EVENT_READY, app);
  lv_obj_add_event_cb(keyboard, on_keyboard, LV_EVENT_CANCEL, app);
  app->keyboard_panel = panel;
  app->keyboard_text = area;
  app->keyboard = keyboard;
}

void h2_g99_ui_set_keyboard_text(h2_g99_app_t* app, const char* text) {
  if (app == NULL || app->keyboard_text == NULL || text == NULL) return;
  lv_textarea_set_text(app->keyboard_text, text);
}

void h2_g99_ui_close_keyboard(h2_g99_app_t* app, char* buffer,
                              size_t capacity) {
  if (buffer != NULL && capacity > 0u) buffer[0] = '\0';
  if (app == NULL || app->keyboard_panel == NULL) return;
  if (buffer != NULL && capacity > 0u)
    (void)snprintf(buffer, capacity, "%s",
                   lv_textarea_get_text(app->keyboard_text));
  lv_obj_delete(app->keyboard_panel);
  app->keyboard_panel = NULL;
  app->keyboard_text = NULL;
  app->keyboard = NULL;
}

/* ---------- init / deinit ---------- */

static bool create_layer(h2_g99_app_t* app, h2_g99_layer_t* layer) {
  layer->wheel = full(app->screen, app);
  if (layer->wheel == NULL) return false;
  lv_obj_set_width(layer->wheel, wheel_width(app));
  layer->poster = image(layer->wheel, &app->library_poster, 0, 0);
  if (layer->poster == NULL) return false;
  lv_obj_set_hidden(layer->poster, true);
  layer->glow = image(layer->wheel, &app->glow, 0, 0);
  if (layer->glow == NULL) return false;
  lv_obj_set_style_image_recolor(layer->glow, lv_color_hex(H2_G99_COLOR_PURPLE),
                                 LV_PART_MAIN);
  for (int i = 0; i < H2_G99_WHEEL_SLOTS; ++i) {
    layer->slots[i] = image(layer->wheel, &app->icons[0], 0, 0);
    layer->slot_src[i] = &app->icons[0];
    if (layer->slots[i] == NULL) return false;
    lv_obj_set_style_image_recolor(layer->slots[i], lv_color_hex(0xFFFFFFu),
                                   LV_PART_MAIN);
    /* A8 uses the colour directly. Transparent recolour opacity preserves
     * the multicolour Orbit cover when the same slot changes source. */
    lv_obj_set_style_image_recolor_opa(layer->slots[i], LV_OPA_TRANSP,
                                       LV_PART_MAIN);
    lv_obj_set_hidden(layer->slots[i], true);
  }
  layer->info = plain(app->screen);
  if (layer->glow == NULL || layer->info == NULL) return false;
  lv_obj_set_pos(layer->info, app->layout.panel_x, app->layout.panel_y);
  lv_obj_set_size(layer->info, app->layout.panel_w, app->layout.panel_h);
  hide_layer(layer);
  return true;
}

static lv_font_t* make_font(int32_t size) {
  lv_font_t* font = lv_tiny_ttf_create_data_ex(
      h2_g99_font_data, h2_g99_font_size, size, LV_FONT_KERNING_NONE, 128u);
  /* Keyboard and textarea symbols live in the built-in symbol font. */
  if (font != NULL) font->fallback = LV_FONT_DEFAULT;
  return font;
}

/* Populate TinyTTF's real bitmap cache before interactive animation.
 * Layout-only glyph metrics do not rasterize these glyphs. */
static bool warm_text(lv_font_t* font, const char* value) {
  /* Only built-in UTF-8 literals reach this initializer. */
  const uint8_t* text = (const uint8_t*)value;
  while (*text != 0u) {
    uint32_t codepoint = *text++;
    if (codepoint >= 0x80u) {
      const unsigned extra = codepoint < 0xe0u   ? 1u
                             : codepoint < 0xf0u ? 2u
                                                 : 3u;
      codepoint &= 0x7fu >> (extra + 1u);
      for (unsigned i = 0u; i < extra; ++i) {
        if ((*text & 0xc0u) != 0x80u) return false;
        codepoint = (codepoint << 6u) | (*text++ & 0x3fu);
      }
    }
    lv_font_glyph_dsc_t glyph;
    memset(&glyph, 0, sizeof(glyph));
    if (!lv_font_get_glyph_dsc(font, &glyph, codepoint, 0u)) return false;
    if (glyph.resolved_font != font || glyph.box_w == 0u || glyph.box_h == 0u)
      continue;
    const void* bitmap = lv_font_get_glyph_bitmap(&glyph, NULL);
    lv_font_glyph_release_draw_data(&glyph);
    if (bitmap == NULL) return false;
  }
  return true;
}

static bool warm_fonts(h2_g99_app_t* app) {
  for (size_t i = 0u; i < H2_G99_MAIN_COUNT; ++i)
    if (!warm_text(app->font_hero, kMainNames[i])) return false;
  for (size_t i = 0u; i < H2_G99_SETTING_COUNT; ++i)
    if (!warm_text(app->font_title, kSettingNames[i])) return false;
  return warm_text(app->font_title, kAppName) &&
         warm_text(app->font_small, kAppAuthor) &&
         warm_text(app->font_small, kAppDescription) &&
         warm_text(app->font_small,
                   "0123456789:/ · 资料库 设置 来源 绘图 输入 OK 开始 AI 返回 "
                   "未连接 未发现网络") &&
         warm_text(app->font_body,
                   "0123456789%Wi-Fi · 已安装 个应用 即将推出 已连接 电量 "
                   "开始游戏 内置 几何 按键") &&
         warm_text(app->font_big, "0123456789%");
}

static bool render_art(h2_g99_app_t* app) {
  const h2_g99_layout_t* l = &app->layout;
  app->icon_px = px(app, 34.0f);
  app->thumb_px = px(app, 50.0f);
  app->glow_px = (int32_t)lroundf((float)app->thumb_px * 1.35f + 6.0f * l->k);
  for (int i = 0; i < H2_G99_ICON_COUNT; ++i) {
    if (!argb_alloc(app, &app->icons[i], app->icon_px, app->icon_px) ||
        !h2_g99_art_icon((h2_g99_icon_t)i, 0xFFFFFFu, app->icons[i].pixels,
                         app->icon_px))
      return false;
    image_to_alpha(app, &app->icons[i]);
  }
  const int32_t tiny = (int32_t)lroundf((float)l->font_small * 1.1f);
  if (!argb_alloc(app, &app->tiny_wifi, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_WIFI, H2_G99_COLOR_MUTED,
                       app->tiny_wifi.pixels, tiny) ||
      !argb_alloc(app, &app->tiny_lock, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_LOCK, H2_G99_COLOR_MUTED,
                       app->tiny_lock.pixels, tiny) ||
      !argb_alloc(app, &app->tiny_check, tiny, tiny) ||
      !h2_g99_art_icon(H2_G99_ICON_CHECK, H2_G99_COLOR_OK,
                       app->tiny_check.pixels, tiny))
    return false;
  if (!argb_alloc(app, &app->cover, app->thumb_px, app->thumb_px) ||
      !h2_g99_art_cover(app->cover.pixels, app->thumb_px) ||
      !argb_alloc(app, &app->glow, app->glow_px, app->glow_px) ||
      !h2_g99_art_glow(app->glow.pixels, app->glow_px))
    return false;
  image_to_alpha(app, &app->glow);
  const int32_t poster_width = l->panel_x + px(app, 24.0f);
  if (!argb_alloc(app, &app->library_poster, poster_width, l->height))
    return false;
  const int32_t source_w = (int32_t)h2_g99_orbit_cover.header.w;
  const int32_t source_h = (int32_t)h2_g99_orbit_cover.header.h;
  const float source_scale = (float)source_h / (float)l->height;
  const float source_left =
      ((float)source_w - (float)poster_width * source_scale) / 2.0f;
  const int32_t fade_start = l->sel_x - px(app, 8.0f);
  const int32_t fade_width = poster_width - fade_start - 1;
  for (int32_t row = 0; row < l->height; ++row) {
    int32_t source_y = (int32_t)((float)row * source_scale);
    if (source_y >= source_h) source_y = source_h - 1;
    for (int32_t column = 0; column < poster_width; ++column) {
      int32_t source_x = (int32_t)(source_left + (float)column * source_scale);
      if (source_x < 0) source_x = 0;
      if (source_x >= source_w) source_x = source_w - 1;
      const uint8_t* source =
          h2_g99_orbit_cover.data +
          ((size_t)source_y * (size_t)source_w + (size_t)source_x) * 4u;
      uint8_t* target =
          app->library_poster.pixels +
          ((size_t)row * (size_t)poster_width + (size_t)column) * 4u;
      const float fade =
          h2_g99_clamp01((float)(column - fade_start) /
                         (float)(fade_width > 0 ? fade_width : 1));
      memcpy(target, source, 3u);
      target[3] = (uint8_t)lroundf((float)source[3] *
                                   (1.0f - fade * fade * (3.0f - 2.0f * fade)));
    }
  }
  const h2_g99_brand_layout_t* brand = &l->brand;
  if (!argb_alloc(app, &app->brand, brand->icon_image_w, brand->icon_image_h) ||
      !h2_g99_art_brand_icon(app->brand.pixels, brand->icon_image_w,
                             brand->icon_image_h) ||
      !argb_alloc(app, &app->mark, brand->wordmark_image_w,
                  brand->wordmark_image_h) ||
      !h2_g99_art_wordmark(app->mark.pixels, brand->cell, brand->shadow))
    return false;
  app->bg_spec = (h2_g99_background_t){l->width, l->height,
                                       l->panel_x - px(app, 24.0f), l->k};
  if (!image_alloc(app, &app->bg, l->width, l->height, LV_COLOR_FORMAT_RGB565,
                   2u))
    return false;
  /* The background is a static picture, drawn once. */
  return h2_g99_background_render(&app->bg_spec, 0u, (uint16_t*)app->bg.pixels,
                                  l->width, 0, l->height);
}

static void free_art(h2_g99_app_t* app) {
  for (int i = 0; i < H2_G99_ICON_COUNT; ++i) image_free(app, &app->icons[i]);
  image_free(app, &app->tiny_wifi);
  image_free(app, &app->tiny_lock);
  image_free(app, &app->tiny_check);
  image_free(app, &app->cover);
  image_free(app, &app->library_poster);
  image_free(app, &app->glow);
  image_free(app, &app->brand);
  image_free(app, &app->mark);
  image_free(app, &app->bg);
}

static const h2_pal_mem_api_t* render_mem(const h2_g99_app_t* app) {
  return app->config->render_mem != NULL ? app->config->render_mem
                                         : app->runtime->mem;
}

h2_pal_result_t h2_g99_ui_init(h2_g99_app_t* app) {
  if (app == NULL || app->lvgl_ready) return H2_PAL_ERR_INVALID_STATE;
  const h2_g99_layout_t* l = &app->layout;
  if (!render_art(app)) {
    free_art(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  /* Bound the fast allocation to one small buffer. All persistent LVGL
   * objects and glyph caches use Runtime memory, not this scarce heap. */
  const int32_t rows = l->height < 16 ? l->height : 16;
  app->render_bytes = (size_t)l->width * (size_t)rows * 2u;
  app->render_buffer = h2_pal_mem_alloc(render_mem(app), app->render_bytes);
  if (app->render_buffer == NULL && rows > 8) {
    app->render_bytes = (size_t)l->width * 8u * 2u;
    app->render_buffer = h2_pal_mem_alloc(render_mem(app), app->render_bytes);
  }
  if (app->render_buffer == NULL) {
    free_art(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  const h2_lvgl_platform_config_t platform = {
      .allocator = app->runtime->mem,
      .task_api = app->runtime->task,
      .sync_api = app->runtime->sync,
      .queue_api = app->runtime->queue,
      .time_api = app->runtime->time,
  };
  if (h2_lvgl_platform_init(&platform) != 0) {
    h2_pal_mem_free(render_mem(app), app->render_buffer);
    app->render_buffer = NULL;
    free_art(app);
    return H2_PAL_ERR_UNAVAILABLE;
  }
  lv_init();
  app->lvgl_ready = true;
  app->last_tick_ms = app->now_ms;
  app->font_hero = make_font(l->font_hero);
  app->font_title = make_font(l->font_title);
  app->font_body = make_font(l->font_body);
  app->font_small = make_font(l->font_small);
  app->font_big = make_font((int32_t)lroundf((float)l->font_title * 1.7f));
  app->display = lv_display_create(l->width, l->height);
  if (app->font_hero == NULL || app->font_title == NULL ||
      app->font_body == NULL || app->font_small == NULL ||
      app->font_big == NULL || app->display == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  if (!warm_fonts(app)) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_display_set_user_data(app->display, app);
  lv_timer_set_period(lv_display_get_refr_timer(app->display), 16u);
  lv_display_set_color_format(app->display, LV_COLOR_FORMAT_RGB565);
  lv_display_set_flush_cb(app->display, display_flush);
  lv_display_set_buffers(app->display, app->render_buffer, NULL,
                         (uint32_t)app->render_bytes,
                         LV_DISPLAY_RENDER_MODE_PARTIAL);
  app->screen = lv_screen_active();
  lv_obj_set_scrollable(app->screen, false);
  lv_obj_set_style_bg_color(app->screen, lv_color_hex(0x000000u), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(app->screen, LV_OPA_COVER, LV_PART_MAIN);
  app->background = image(app->screen, &app->bg, 0, 0);
  app->catcher = full(app->screen, app);
  if (app->background == NULL || app->catcher == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_obj_set_style_opa(app->background, LV_OPA_TRANSP, LV_PART_MAIN);
  lv_obj_set_clickable(app->catcher, true);
  lv_obj_set_press_lock(app->catcher, true);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESSED, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESSING, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_RELEASED, app);
  lv_obj_add_event_cb(app->catcher, on_catcher, LV_EVENT_PRESS_LOST, app);
  if (!create_layer(app, &app->layers[0]) ||
      !create_layer(app, &app->layers[1])) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  app->brand_icon =
      image(app->screen, &app->brand, l->brand.icon_x, l->brand.group_y);
  app->wordmark =
      image(app->screen, &app->mark, l->brand.wordmark_x, l->brand.wordmark_y);
  app->blackout =
      rect(app->screen, 0, 0, l->width, l->height, 0x000000u, LV_OPA_COVER, 0);
  if (app->brand_icon == NULL || app->wordmark == NULL ||
      app->blackout == NULL) {
    h2_g99_ui_deinit(app);
    return H2_PAL_ERR_NO_MEMORY;
  }
  lv_obj_set_hidden(app->blackout, true);
  const h2_pal_touch_api_t* source =
      app->config->touch != NULL ? app->config->touch : app->runtime->touch;
  if (source != NULL) {
    /* LVGL reads touch through the filter: one press per contact. */
    h2_g99_touch_filter_init(&app->touch_filter, source, app->runtime->time);
    const h2_lvgl_touch_config_t touch = {
        h2_g99_touch_filter_api(&app->touch_filter), app->runtime->mem,
        app->display};
    if (h2_lvgl_touch_create(&touch, &app->touch) != H2_PAL_OK) {
      app->touch = NULL;
    } else {
      for (lv_indev_t* indev = lv_indev_get_next(NULL); indev != NULL;
           indev = lv_indev_get_next(indev)) {
        /* Sample at the filter's cadence instead of the display's refresh
         * period, which can leave a quick gesture unread between frames. */
        lv_timer_t* timer = lv_indev_get_read_timer(indev);
        if (timer != NULL) lv_timer_set_period(timer, H2_G99_TOUCH_READ_MS);
        lv_indev_add_event_cb(indev, on_indev_press, LV_EVENT_PRESSED, app);
      }
    }
  }
  app->touch_request = (h2_g99_touch_request_t){.action = -1,
                                                .row = -1,
                                                .value = -1,
                                                .text = H2_G99_TEXT_NONE,
                                                .wifi_focus = -1,
                                                .haptics = -1,
                                                .timeout = -1,
                                                .library_menu = -1};
  return H2_PAL_OK;
}

void h2_g99_ui_deinit(h2_g99_app_t* app) {
  if (app == NULL) return;
  if (app->lvgl_ready) {
    clear_library_menu(app);
    if (app->touch != NULL) h2_lvgl_touch_destroy(app->touch);
    app->touch = NULL;
    app->keyboard_panel = NULL;
    lv_font_t** fonts[] = {&app->font_hero, &app->font_title, &app->font_body,
                           &app->font_small, &app->font_big};
    if (app->display != NULL) lv_display_delete(app->display);
    app->display = NULL;
    for (size_t i = 0; i < sizeof(fonts) / sizeof(fonts[0]); ++i) {
      if (*fonts[i] != NULL) lv_tiny_ttf_destroy(*fonts[i]);
      *fonts[i] = NULL;
    }
    lv_deinit();
    h2_lvgl_platform_deinit();
    app->lvgl_ready = false;
  }
  if (app->render_buffer != NULL)
    h2_pal_mem_free(render_mem(app), app->render_buffer);
  app->render_buffer = NULL;
  free_art(app);
}
